const controllers=new WeakMap();
let opened=null,sequence=0;
function enhance(select){
 if(controllers.has(select)||select.multiple||select.size>1)return;
 const wrapper=document.createElement('div');wrapper.className='custom-select';select.before(wrapper);wrapper.append(select);select.classList.add('native-select');select.tabIndex=-1;select.setAttribute('aria-hidden','true');
 const trigger=document.createElement('button');trigger.type='button';trigger.className='select-trigger';trigger.setAttribute('role','combobox');trigger.setAttribute('aria-haspopup','listbox');trigger.setAttribute('aria-expanded','false');
 const label=document.createElement('span'),chevron=document.createElement('span');chevron.className='select-chevron';chevron.innerHTML='<svg viewBox="0 0 20 20" width="15" height="15" fill="none" stroke="currentColor" stroke-width="1.6"><path d="m5 7 5 5 5-5"/></svg>';trigger.append(label,chevron);wrapper.append(trigger);
 const panel=document.createElement('div');panel.className='select-popover';panel.popover='manual';panel.id='custom-options-'+(++sequence);trigger.setAttribute('aria-controls',panel.id);wrapper.append(panel);
 let search=null;if(select.options.length>7){search=document.createElement('input');search.type='search';search.className='select-search';search.placeholder='Cari pilihan…';search.setAttribute('aria-label','Cari pilihan');panel.append(search);}
 const list=document.createElement('div');list.className='select-options';list.setAttribute('role','listbox');list.setAttribute('aria-label',select.getAttribute('aria-label')||select.labels?.[0]?.textContent||'Pilihan');panel.append(list);
 const options=Array.from(select.options).map((option,i)=>{const button=document.createElement('button');button.type='button';button.role='option';button.id=panel.id+'-'+i;button.tabIndex=-1;button.className='select-option';button.disabled=option.disabled;const text=document.createElement('span'),tick=document.createElement('span');text.textContent=option.textContent;tick.className='select-option-tick';tick.textContent='✓';button.append(text,tick);list.append(button);button.addEventListener('click',()=>{select.value=option.value;select.dispatchEvent(new Event('change',{bubbles:true}));close();trigger.focus();});return {button,option};});
 const empty=document.createElement('p');empty.className='select-empty';empty.textContent='Tidak ada pilihan yang cocok';empty.hidden=true;list.append(empty);
 let active=-1,typed='',typingTimer;
 const sync=()=>{label.textContent=select.selectedOptions[0]?.textContent||'Pilih…';trigger.disabled=select.disabled;trigger.setAttribute('aria-label',(select.getAttribute('aria-label')||select.labels?.[0]?.textContent||select.name||'Pilihan')+': '+label.textContent);options.forEach(({button,option})=>button.setAttribute('aria-selected',String(option.selected)));};
 const focusOption=i=>{if(i<0)return;active=i;options.forEach(({button},j)=>button.classList.toggle('is-active',i===j));trigger.setAttribute('aria-activedescendant',options[i].button.id);search?.setAttribute('aria-activedescendant',options[i].button.id);options[i].button.scrollIntoView({block:'nearest'});};
 const position=()=>{if(!panel.matches(':popover-open'))return;const r=trigger.getBoundingClientRect(),availableBelow=innerHeight-r.bottom-12,up=availableBelow<180&&r.top>availableBelow;panel.style.width=Math.max(180,Math.min(r.width,innerWidth-24))+'px';panel.style.left=Math.max(12,Math.min(r.left,innerWidth-panel.offsetWidth-12))+'px';panel.style.maxHeight=Math.max(110,Math.min(320,up?r.top-20:availableBelow))+'px';panel.style.top=(up?Math.max(12,r.top-panel.offsetHeight-7):r.bottom+7)+'px';};
 function close(){if(panel.matches(':popover-open'))panel.hidePopover();trigger.setAttribute('aria-expanded','false');trigger.removeAttribute('aria-activedescendant');wrapper.classList.remove('is-open');if(opened?.panel===panel)opened=null;}
 function open(){if(trigger.disabled)return;opened?.close();if(search){search.value='';options.forEach(o=>o.button.hidden=false);empty.hidden=true;}panel.showPopover();trigger.setAttribute('aria-expanded','true');wrapper.classList.add('is-open');opened={panel,wrapper,close,position};position();focusOption(Math.max(0,select.selectedIndex));if(search)search.focus();}
 trigger.addEventListener('click',()=>panel.matches(':popover-open')?close():open());
 function keydown(event){const visible=options.map((o,i)=>!o.button.hidden&&!o.button.disabled?i:-1).filter(i=>i>=0);let next=active;
  if(['ArrowDown','ArrowUp','Home','End','Enter','Escape',' '].includes(event.key)){
   if(event.key==='Escape'){if(panel.matches(':popover-open')){event.preventDefault();event.stopPropagation();close();trigger.focus();}return;}
   if(event.key===' '&&event.target===search)return;
   event.preventDefault();if(!panel.matches(':popover-open')){open();return;}
   if(event.key==='Enter'||event.key===' '){options[active]?.button.click();return;}
   let index=visible.indexOf(active);if(event.key==='ArrowDown')next=visible[(index+1)%visible.length];if(event.key==='ArrowUp')next=visible[(index-1+visible.length)%visible.length];if(event.key==='Home')next=visible[0];if(event.key==='End')next=visible.at(-1);focusOption(next??-1);
  }else if(event.key==='Tab'){close();}else if(event.key.length===1&&event.target!==search){clearTimeout(typingTimer);typed+=event.key.toLowerCase();const match=options.findIndex(o=>!o.button.disabled&&o.option.textContent.toLowerCase().startsWith(typed));if(!panel.matches(':popover-open'))open();focusOption(match);typingTimer=setTimeout(()=>typed='',650);}
 }
 trigger.addEventListener('keydown',keydown);panel.addEventListener('keydown',keydown);search?.addEventListener('input',()=>{const term=search.value.trim().toLowerCase();options.forEach(o=>o.button.hidden=!o.option.textContent.toLowerCase().includes(term));empty.hidden=options.some(o=>!o.button.hidden);focusOption(options.findIndex(o=>!o.button.hidden&&!o.button.disabled));position();});
 select.addEventListener('change',sync);select.addEventListener('focus',()=>trigger.focus());select.addEventListener('invalid',event=>{event.preventDefault();trigger.focus();open();});select.form?.addEventListener('reset',()=>setTimeout(sync,0));controllers.set(select,{sync});sync();
}
export function initializeControls(){document.querySelectorAll('select').forEach(enhance);document.querySelectorAll('[data-duration-picker]').forEach(syncDuration);}
function syncDuration(picker){const hours=picker.querySelector('[name="hours"]'),minutes=picker.querySelector('[name="minutes"]'),total=Number(hours.value)*60+Number(minutes.value);minutes.setCustomValidity(total<1||total>43200?'Pilih durasi antara 1 menit dan 720 jam.':'');picker.querySelectorAll('[data-duration-hours]').forEach(button=>{const chosen=Number(button.dataset.durationHours)*60===total;button.classList.toggle('chosen',chosen);button.setAttribute('aria-pressed',String(chosen));});}
document.addEventListener('click',event=>{if(opened&&!opened.wrapper.contains(event.target))opened.close();const preset=event.target.closest('[data-duration-hours]');if(preset){const picker=preset.closest('[data-duration-picker]');picker.querySelector('[name="hours"]').value=preset.dataset.durationHours;picker.querySelector('[name="minutes"]').value=0;syncDuration(picker);picker.classList.remove('duration-updated');void picker.offsetWidth;picker.classList.add('duration-updated');}});
document.addEventListener('input',event=>{const picker=event.target.closest('[data-duration-picker]');if(picker)syncDuration(picker);});
window.addEventListener('resize',()=>opened?.position());document.addEventListener('scroll',event=>{if(opened&&!opened.panel.contains(event.target))opened.position();},true);
document.addEventListener('live:updated',initializeControls);initializeControls();
